    "Correta (E). Conforme a resolução: A “Cortina de Ferro” citada no texto faz referência aos países do leste europeu que pertenciam à ex-URSS ou estavan alinhados ao bloco socialista. Essa situação geopolítica marcou, entre as décadas de 1940 e 1990, a denominada Guerra Fria, que dividiu fisicamente a Europa em Leste e Oeste com preceitos ideológicos (socialistas e capitalistas, respectivamente)."
