    "1 corresponde à navegação de cabotagem, eficiente para o transporte em grandes distâncias.",
    "1 corresponde ao deslocamento aéreo, competitivo no transporte de mercadorias de alto valor agregado.",
    "3 corresponde ao sistema ferroviário, capaz de absorver os impactos econômicos no transporte de rejeitos industriais.",
