  "difficulty": "Média",
  "statement": "Classificação dos estados de criticidade\n\n• Entre 21 e 30% – Estado de Atenção – Evitar exercícios físicos ao ar livre entre 11 e 15 horas; – Utilizar toalhas molhadas, recipientes com água, irrigar\n\njardins etc.; – Sempre que possível, permanecer em locais protegidos\n\ndo sol, em áreas vegetadas etc.; – Consumir água à vontade.\n\n• Entre 12 e 20% – Estado de Alerta – Observar as recomendações do Estado de Atenção; – Suprimir exercícios físicos e trabalhos ao ar livre entre 10\n\ne 16 horas; – Evitar aglomerações em ambientes fechados; – Usar soro fisiológico para olhos e narinas.\n\n• Abaixo de 12% – Estado de Emergência – Observar as recomendações para os Estados de Atenção\n\ne de Alerta; – Determinar a interrupção de qualquer atividade ao ar livre\n\nentre 10 e 16 horas, como aulas de educação física, coleta de lixo, entrega de correspondência etc.; – Determinar a suspensão de atividades que exijam aglomerações de pessoas em recintos fechados, como aulas, cinemas etc., entre 10 e 16 horas.\n\n(www.cgesp.org. Adaptado.)\n\nAs recomendações descritas devem ser adotadas quando houver",
