  "difficulty": "Média",
  "statement": "Um novo estudo realizado pela Escola Nacional de Saúde Pública Sergio Arouca (ENSP/Fiocruz) na população indígena Yanomami constatou a presença de mercúrio nas amostras de cabelo de 56% das mulheres e crianças da região de Maturacá, no Amazonas, em níveis acima do tolerado pela Organização Mundial da Saúde. “O mercúrio é disseminado pelas águas dos rios e a contaminação de seres humanos se dá, especialmente, por meio da ingestão de peixes contaminados”, afirmou o coordenador da pesquisa, Paulo Basta.\n\n(Filipe Leonel. “Contaminação por mercúrio se alastra na população\n\nYanomami”. www.ensp.fiocruz.br, 16.08.2019. Adaptado.)\n\nA contaminação por mercúrio apresentada no excerto está associada",
