  "statement": "Uma das questões ainda não respondidas pela Ciência é sobre a origem dos vírus, se teriam surgido antes ou depois das primeiras células procariontes. Os pesquisadores apontam evidências e apresentam argumentos em favor de cada uma das hipóteses, mas ainda não há resposta definitiva sobre o tema. Em uma discussão entre dois alunos sobre qual dos micro-organismos surgiu primeiro no mundo, bactérias ou vírus, cinco argumentos foram apresentados. Destes, o mais correto, de acordo com os conhecimentos acerca desses micro-organismos, é:",
