  "difficulty": "Média",
  "statement": "As fotocélulas são dispositivos utilizados como substitutos de interruptores que acendem as lâmpadas de uma casa ou de postes na rua. Esses dispositivos baseiam seu funcionamento no efeito fotoelétrico, como ilustra a figura.\n\n(Álvaro M. Barcelos. Propriedades Químicas. Adaptado.)",
