    "Correta (D). Conforme a resolução: Em órbita circular estável, a força gravitacional atua como resultante centrípeta: $F_G = F_{cp} \\implies G\\frac{M m}{r^2} = m \\omega^2 r$. Sendo $\\omega = \\frac{2\\pi}{T}$, temos $r^3 = \\frac{G M T^2}{4\\pi^2} \\implies r = \\sqrt[3]{\\frac{G M T^2}{4\\pi^2}}$. Como o satélite é estacionário em relação ao astro, seu período orbital $T$ é igual ao período de rotação do astro. Portanto, o raio $r$ depende apenas da massa do astro ($M$) e de seu período de rotação ($T$).",
    "Incorreta (E). Esta opção não condiz com as exigências teóricas ou matemáticas da questão. A resposta correta e comprovada pelos fundamentos da matéria é a alternativa D."
