  "answer": "B",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "$m_{\\text{água}} \\cdot 4{,}2 \\times 10^3 \\cdot (-10) + 0{,}42 \\cdot 9{,}0 \\times 10^2 \\cdot 50 = 0 \\implies m_{\\text{água}} = 0{,}45\\ \\mathrm{kg} = 450\\ \\mathrm{g}$."
  ],
  "resolutionMatched": true,
  "correctionOrigin": "official",
