    "Correta (B). Conforme a resolução: Sistema isolado termicamente: $Q_{\\text{água}} + Q_{\\text{Al}} = 0$. Com temperatura de equilíbrio $\\theta = 70^\\circ\\mathrm{C}$: $m_{\\text{água}} c_{\\text{água}} (70 - 80) + m_{\\text{Al}} c_{\\text{Al}} (70 - 20) = 0 \\implies m_{\\text{água}} \\cdot 4{,}2 \\times 10^3 \\cdot (-10) + 0{,}42 \\cdot 9{,}0 \\times 10^2 \\cdot (50) = 0 \\implies -4{,}2 \\times 10^4 m_{\\text{água}} + 1{,}89 \\times 10^4 = 0 \\implies m_{\\text{água}} = 0{,}45\\ \\mathrm{kg} = 450\\ \\mathrm{g}$.",
    "Incorreta (C). Esta opção não condiz com as exigências teóricas ou matemáticas da questão. A resposta correta e comprovada pelos fundamentos da matéria é a alternativa B.",
