  "statement": "Nas Ciências, muitas vezes, se inicia o estudo de um problema fazendo uma aproximação simplificada. Um desses casos é o estudo do comportamento da membrana celular devido à distribuição do excesso de íons positivos e negativos em torno dela. A figura mostra a visão geral de uma célula e a analogia entre o modelo biológico e o modelo físico, o qual corresponde a duas placas planas e paralelas, eletrizadas com cargas elétricas de tipos opostos.\n\n(http://bioquimica.org.br. Adaptado.)",
